package rentivo_backend.controller;
import org.springframework.security.core.Authentication; import org.springframework.web.bind.annotation.*; import rentivo_backend.dto.SubscriptionDtos.*; import rentivo_backend.service.SubscriptionService;
@RestController @RequestMapping("/api/subscriptions") public class SubscriptionController {private final SubscriptionService s;public SubscriptionController(SubscriptionService s){this.s=s;} private Long uid(Authentication a){return (Long)a.getPrincipal();} @GetMapping("/plans") public Object plans(){return s.plans();} @PostMapping("/activate-dev") public Object activate(@RequestParam Long planId,Authentication a){return s.activate(uid(a),planId);} @GetMapping("/status") public Status status(Authentication a){return s.status(uid(a));} @PostMapping("/contact/{listingId}") public ContactResponse contact(@PathVariable Long listingId,Authentication a){return s.unlock(uid(a),listingId);} }
